<?php require 'conexion.php';$d=body();$correo=strtolower(trim($d['correo']??''));$pass=$d['contrasena']??'';$s=$pdo->prepare('SELECT id,nombre,celular,correo,contrasena,lat,lng FROM usuarios WHERE correo=?');$s->execute([$correo]);$u=$s->fetch();if(!$u||!password_verify($pass,$u['contrasena']))out(['ok'=>false,'mensaje'=>'Correo o contraseña incorrectos.'],401);unset($u['contrasena']);out(['ok'=>true,'usuario'=>$u]);
